mapper.select:
SELECT m.id, m.user_id, u.username, u.nickname, m.manufacturer_id, mf.name AS manufacturer_name, m.name, m.price, m.remark, m.sold, m.is_public, m.view_count, m.favorite_count, m.cover, m.created_at, m.updated_at FROM model m LEFT JOIN manufacturer mf ON m.manufacturer_id = mf.id AND mf.deleted = 0 LEFT JOIN user u ON m.user_id = u.id WHERE m.deleted = 0
AND m.user_id = #{dto.userId}
AND mf.name LIKE CONCAT('%', #{dto.manufacturerName}, '%')
AND m.name LIKE CONCAT('%', #{dto.modelName}, '%')
AND m.price >= #{dto.minPrice}
AND m.price <= #{dto.maxPrice}
AND m.sold = #{dto.sold}
AND m.is_public = #{dto.isPublic}
ORDER BY m.created_at DESC

SELECT m.manufacturer_id, mf.name AS manufacturer_name, COUNT(m.id) AS model_count, SUM(m.price) AS total_price FROM model m LEFT JOIN manufacturer mf ON m.manufacturer_id = mf.id AND mf.deleted = 0 WHERE m.deleted = 0
AND m.user_id = #{userId}
GROUP BY m.manufacturer_id, mf.name ORDER BY model_count DESC

mapper.update:
UPDATE model
SET favorite_count = favorite_count + #{delta}
WHERE id = #{id}

UPDATE model
SET view_count = view_count + 1
WHERE id = #{id}
